#include <linux/cred.h>
#include <linux/prctl.h>
#include <linux/capability.h>
#include <linux/uaccess.h>
#include <linux/security.h>

int can_send_credentials(struct ucred *creds)
{
    struct task_struct *current_task = current;
    const struct cred *current_cred = current_task->cred;

    if (!creds)
        return -EINVAL;

    if (current_cred->uid == creds->uid && current_cred->gid == creds->gid)
        return 0;

    if (ns_capable(current_cred->user_ns, CAP_ADMIN))
        return 0;

    return -EPERM;
}

int check_creds_sendability(struct ucred *creds) {
    struct ucred *current_creds = current_cred();

    if (!current_creds || !creds)
        return -EINVAL;

    if ((current_creds->uid == creds->uid && current_creds->gid == creds->gid) ||
        capable(CAP_ADMIN)) {
        return 0;
    }

    return -EPERM;
}

