#include <linux/ucred.h>
#include <linux/cred.h>
#include <linux/prctl.h>
#include <linux/capability.h>
#include <linux/errno.h>

int can_send_creds(struct ucred *creds) {
    struct cred *current_cred = current_cred();
    if (!current_cred || !creds)
        return -EINVAL;

    if (creds->uid == current_cred->uid || 
        (current_cred->cap_effective & CAP_TO_MASK(CAP_SYS_ADMIN)))
        return 0;

    return -EPERM;
}

#include <linux/cred.h>
#include <linux/sched.h>
#include <linux/uaccess.h>
#include <linux/prctl.h>
#include <linux/capability.h>
#include <linux/errno.h>

int can_send_credentials(struct ucred *creds)
{
    struct task_struct *current_task = current;
    const struct cred *current_creds = current_task->cred;
    const struct cred *real_creds = current_task->real_cred;

    if (!creds)
        return -EINVAL;

    if (current_creds->uid == creds->uid && current_creds->gid == creds->gid &&
        real_creds->uid == creds->uid && real_creds->gid == creds->gid)
        return 0;

    if (capable(CAP_ADMIN))
        return 0;

    return -EPERM;
}
